INSERT INTO "articulos_academicos" VALUES ('101', 'Revista Iberoamericana de Derecho Constitucional —año I– Número I, Ciudad Autónoma de Buenos Aires, noviembre de 2003.', NULL, '2003-01-01 00:00:00', 'Propiedad', NULL, '0', NULL, '2026-07-20 22:22:14', '2026-07-20 22:22:14', 'https://marcelabasterra.com.ar/wp-content/uploads/2016/11/El-derecho-de-propiedad-en-la-Argentina.pdf');
