INSERT INTO "blog" VALUES ('5', '<p>Un sistema electoral que pide reformas / Clarín</p>', 'Un sistema electoral que pide reformas / Clarín', NULL, '2015-09-29 02:19:32', '2026-07-21 18:27:58', '2026-07-21 18:55:48', '0');
INSERT INTO "blog" VALUES ('6', '<p>Un Crimen Grabado en la Conciencia Universal / Infobae</p>', 'Un Crimen Grabado en la Conciencia Universal / Infobae', 'blog/imported-6.jpg', '2015-04-24 21:53:36', '2026-07-21 18:27:58', '2026-07-21 18:56:08', '0');
INSERT INTO "blog" VALUES ('7', '<p>En el 2017 se llevó a cabo otra edición del <strong>Taller Cuento con Derechos</strong> en 6 organizaciones diferentes de la Ciudad de Buenos Aires. La Dra. Basterra impulsa el programa que coordina Jessica Malegaríe desde la Dirección de Acceso Comunitario a la Justicia del Consejo de la Magistratura de CABA.</p>
INSERT INTO "blog" VALUES ('8', '<p>El acuerdo fue suscrito en el Barrio 20 de Villa Lugano, en el marco de una actividad realizada entre el Consejo de la Magistratura CABA y el Ministerio de Hábitat y Desarrollo Humano.</p>
INSERT INTO "blog" VALUES ('9', '<p>Empleados, funcionarios y autoridades del Poder Judicial participaron de la reunión.</p>
INSERT INTO "blog" VALUES ('10', '<p>Se votó la aceptación de la Ley N° 26.702 en la Legislatura Porteña. Y con ella se transfieren competencias penales de la Justicia Ordinaria Nacional a la Ciudad de Buenos Aires.</p>
INSERT INTO "blog" VALUES ('11', '<p>Con motivo de la conmemoración de la Semana de la Discapacidad, la Oficina de Atención e Integración de Personas con Discapacidad, dependiente del Departamento de Desarrollo Humano del Consejo, realizó diversas actividades y reconocimientos en la librería de la Editorial Jusbaires.</p>
INSERT INTO "blog" VALUES ('12', '<p>Palabras para la Igualdad / Día Internacional de la Mujer</p>', 'Palabras para la Igualdad / Día Internacional de la Mujer', 'blog/imported-12.jpg', '2018-02-22 22:52:47', '2026-07-21 18:27:58', '2026-07-21 18:56:08', '0');
INSERT INTO "blog" VALUES ('13', '<p>El acuerdo firmado propone una acción de Cooperación Académica entre el Consejo de la Magistratura de la CABA y la Facultad de Derecho.</p>
INSERT INTO "blog" VALUES ('14', '<p>Reflexiones breves sobre los veinte años de la Justicia porteña / Revista Pensar Jusbaires</p>', 'Reflexiones breves sobre los veinte años de la Justicia porteña / Revista Pensar Jusbaires', 'blog/imported-14.jpg', '2018-02-27 16:31:29', '2026-07-21 18:27:58', '2026-07-21 18:56:08', '0');
INSERT INTO "blog" VALUES ('15', '<p>Avances y desafíos / Revista Entre Todos Ciudad</p>', 'Avances y desafíos / Revista Entre Todos Ciudad', 'blog/imported-15.jpg', '2018-01-28 16:53:20', '2026-07-21 18:27:58', '2026-07-21 18:56:08', '0');
INSERT INTO "blog" VALUES ('16', '<p>Una necesaria y ambiciosa reforma judicial / Urgente 24</p>', 'Una necesaria y ambiciosa reforma judicial / Urgente 24', 'blog/imported-16.jpg', '2018-03-22 19:08:46', '2026-07-21 18:27:58', '2026-07-21 18:56:08', '0');
INSERT INTO "blog" VALUES ('17', '<p>“La protección de datos personales resguarda los datos falsos y discriminatorios” / Contexto Político</p>', '“La protección de datos personales resguarda los datos falsos y discriminatorios” / Contexto Político', 'blog/imported-17.jpeg', '2015-06-15 22:02:35', '2026-07-21 18:27:58', '2026-07-21 18:56:08', '0');
INSERT INTO "blog" VALUES ('18', '<p>El acuerdo se firmó con el Secretario de Asuntos Políticos e Institucionales del Ministerio del Interior y propone bases generales de coordinación y colaboración para actividades futuras conjuntas en materia de Acceso a la Justicia con el Consejo.</p>
INSERT INTO "blog" VALUES ('19', '<p>La mujer y el servicio de Justicia / Revista El Cronista</p>', 'La mujer y el servicio de Justicia / Revista El Cronista', 'blog/imported-19.jpg', '2018-05-01 21:51:35', '2026-07-21 18:27:58', '2026-07-21 18:56:08', '0');
INSERT INTO "blog" VALUES ('20', '<p>El acuerdo propone un acuerdo de cooperación técnica entre el Consejo de la Magistratura y la Asociación Argentina de Profesores de Derecho Procesal Penal.</p>
INSERT INTO "blog" VALUES ('21', '<p>El encuentro se desarrolló en la Facultad de Derecho de la UBA y fue organizado por la Presidencia del Consejo de la Magistratura de la Ciudad.</p>
INSERT INTO "blog" VALUES ('22', '<p>El acuerdo firmado propone un marco de cooperación entre el Consejo de la Magistratura de la CABA y las Comunas.</p>
INSERT INTO "blog" VALUES ('23', '<p>En la reunión de la Comisión de Interpretación del Convenio Colectivo de Trabajo se incorporó la licencia por violencia de género y/o familiar.</p>
INSERT INTO "blog" VALUES ('24', '<p>Los alumnos visitaron el organismo y conversaron con la Dr. Marcela I. Basterra y los consejeros sobre el trabajo que realiza la institución.</p>
INSERT INTO "blog" VALUES ('25', '<p>Las actividades se llevarán a cabo del 26 de abril al 14 de mayo en el stand institucional, ubicado en el pabellón Ocre.</p>
INSERT INTO "blog" VALUES ('26', '<p>Otra participación más del Consejo en la Feria del Libro, con más de 80 actividades y 13 publicaciones de altísima calidad.</p>
INSERT INTO "blog" VALUES ('27', '<p>¿Por qué una Ley de Acceso a la Información Pública? / Sección Política</p>', '¿Por qué una Ley de Acceso a la Información Pública? / Sección Política', 'blog/imported-27.jpg', '2015-04-08 22:12:58', '2026-07-21 18:27:58', '2026-07-21 18:56:09', '0');
INSERT INTO "blog" VALUES ('28', '<p>El libro fue realizado por el Observatorio de Género en la Justicia porteña y editado por la Editorial Jusbaires.</p>
INSERT INTO "blog" VALUES ('29', '<p>La actividad se llevó a cabo en el marco del proceso de transferencia de competencias a la órbita local que aguarda ser refrendada por el Congreso Nacional.</p>
INSERT INTO "blog" VALUES ('30', '<p>Se inició un conservatorio sobre acceso justicia con referentes barriales y funcionarios voluntarios del Poder Judicial.</p>
INSERT INTO "blog" VALUES ('31', '<p>La Presidenta del Consejo Marcela I. Basterra participó en la actividad de Editorial Jusbaires.</p>
INSERT INTO "blog" VALUES ('32', '<p>Esta obra se pregunta cuál es la tarea del juez constitucional entre otros temas fundamentales como los procesos constitucionales.</p>
INSERT INTO "blog" VALUES ('33', '<p>El mismo contempla la posibilidad de realizar las acciones tendientes a fomentar la mutua complementación y cooperación que contribuyan al respectivo desarrollo institucional.</p>
INSERT INTO "blog" VALUES ('34', '<p>El equipo de trabajo se encontró con nuevos voluntarios del Poder Judicial CABA para planificar las próximas acciones.</p>
INSERT INTO "blog" VALUES ('35', '<p>Este nuevo espacio permite que los menores de edad que tengan que declarar, lo hagan en una única declaración, evitando su revictimización.</p>
INSERT INTO "blog" VALUES ('36', '<p>El encuentro fue organizado por el Ministerio de Justicia y Derechos Humanos de la Nación, el Tribunal Superior de Justicia de la Ciudad y la Comisión Iberoamericana de Ética Judicial.</p>
INSERT INTO "blog" VALUES ('37', '<p>El mismo fue suscrito considerando la aplicación de normas de calidad elaboradas por la Organización Internacional para la Normalización (ISO), en pos de promover mejoras en la actividad de organizaciones públicas y privadas.</p>
INSERT INTO "blog" VALUES ('38', '<p>Restricciones que podrían obstaculizar el proceso democrático / Infobae</p>', 'Restricciones que podrían obstaculizar el proceso democrático / Infobae', 'blog/imported-38.jpg', '2014-10-30 22:20:09', '2026-07-21 18:27:58', '2026-07-21 18:56:09', '0');
INSERT INTO "blog" VALUES ('39', '<p>La finalidad es trabajar en conjunto acciones para debilitar y concientizar sobre violencia en la red.</p>
INSERT INTO "blog" VALUES ('40', '<p>En el acto se homenajeó a los grandes juristas por su trabajo por la Democracia y los Derechos Humanos.</p>
INSERT INTO "blog" VALUES ('41', '<p>La Dra. Marcela I. Basterra participó de la apertura de la actividad organizada por la Comisión de Transferencia del Poder Judicial de la Nación y del Ministerio Público de la Nación a la Ciudad Autónoma de Buenos Aires.</p>
INSERT INTO "blog" VALUES ('42', '<p>Se realizó un taller de debate, con el orgullo de trabajar por la fortaleza de las instituciones y el acceso a la justicia.</p>
INSERT INTO "blog" VALUES ('43', '<p>La misma tuvo como eje de debate la “Tensión entre las demandas de seguridad y libertad anticipada del condenado”.</p>
INSERT INTO "blog" VALUES ('44', '<p>Continúa el avance de la innovación judicial de la CABA con el Programa Expediente Judicial Electrónico para garantizar un eficaz y transparente servicio de justicia.</p>
INSERT INTO "blog" VALUES ('45', '<p>Columna de opinión originalmente publicada en <a href="https://www.infobae.com/opinion/2018/06/28/dia-del-orgullo-gay-por-que-la-igualdad-formal-es-insuficiente/">infobae.com</a>.</p>
INSERT INTO "blog" VALUES ('46', '<p>“En 20 años, la Ciudad no tuvo una denuncia de corrupción contra un juez” / La Política Online</p>', '“En 20 años, la Ciudad no tuvo una denuncia de corrupción contra un juez” / La Política Online', 'blog/imported-46.jpg', '2018-07-02 18:45:27', '2026-07-21 18:27:58', '2026-07-21 18:56:09', '0');
INSERT INTO "blog" VALUES ('47', '<p>Más de 40 periodistas pertenecientes a medios gráficos, radiales, televisivos y online participaron de la convocatoria.</p>
INSERT INTO "blog" VALUES ('48', '<p>Los especialistas trabajaron en base a la experiencia citada por un especialista italiano, los ámbitos de aplicación local y el traspaso de competencias de la Nación a la órbita porteña.</p>
INSERT INTO "blog" VALUES ('49', '<p>El miércoles 8 y el jueves 9 de junio se desarrollaron las jornadas en Conmemoración de los 20 años de la sanción de la Constitución de la Ciudad de Buenos Aires que organizó la Comisión de Fortalecimiento Institucional y Planificación Estratégica que dirige la Dra. Marcela Basterra en el Consejo de la Magistratura de CABA.</p>
INSERT INTO "blog" VALUES ('50', '<p>La nueva publicación de la Dra. Marcela I. Basterra fue co-editada por Editorial Jusbaires y Editorial Astrea.</p>
INSERT INTO "blog" VALUES ('51', '<p>El documento analiza el cruce entre género y racismo desde una perspectiva de derechos humanos.</p>
INSERT INTO "blog" VALUES ('52', '<p>Diseñamos un manifiesto que explica el Programa de Acceso a la Justicia y sus puntos fundamentales.</p>
INSERT INTO "blog" VALUES ('53', '<p>La Presidenta y el Vicepresidente del Consejo promueven una herramienta para profundizar la calidad institucional en la justicia porteña.</p>
INSERT INTO "blog" VALUES ('54', '<p>Los alumnos participaron y obtuvieron el primer puesto en el VI Concurso de Simulación Judicial ante la Corte Penal Internacional en La Haya y el Concurso de Arbitraje Internacional de París.</p>
INSERT INTO "blog" VALUES ('55', '<p>La actividad estuvo organizada por el Consejo de la Magistratura de la Nación.</p>
INSERT INTO "blog" VALUES ('56', '<p>El convenio busca fomentar la mutua complementación y cooperación.</p>
INSERT INTO "blog" VALUES ('57', '<p>El mismo fue suscrito entre el Ministerio de Justicia y Derechos Humanos de la Nación y el Consejo de la Magistratura para implementar medidas que promuevan la integridad y transparencia en la gestión de asuntos públicos bajo la órbita de sus respectivas competencias.</p>
INSERT INTO "blog" VALUES ('58', '<p>El martes 4 de septiembre en el Aula 1 de Extensión Universitaria de la Facultad de Derecho (UBA) se presentó la obra colectiva que coordinó Damián Azrak desde la Asociación de Derecho Administrativo de la Ciudad Autónoma de Buenos Aires.</p>
INSERT INTO "blog" VALUES ('59', '<p>Llegamos a ⁦Casa Trans⁩, un espacio de contención, sociabilidad y protección de los derechos #LGBT y la primera casa en Latinoamérica y el Caribe para seguir profundizando en el Acceso a la Justicia.</p>
INSERT INTO "blog" VALUES ('60', '<p>La Dra. Marcela I. Basterra participó, como Consejera del Consejo de la Magistratura de la Ciudad Autónoma de Buenos Aires, de la charla en conjunto a la Secretaría de Coordinación de Políticas Judiciales sobre Acceso a la Justicia. La exposición se dio en el marco de la 42ª Feria Internacional del Libro de Buenos Aires el pasado lunes 9 de mayo en la Sala Alfonsina Storni.</p>
INSERT INTO "blog" VALUES ('61', '<p>El acuerdo tiene como objetivo contribuir con equipamiento informático a jóvenes en conflicto con la ley penal.</p>
INSERT INTO "blog" VALUES ('62', '<p>El encuentro se llevó a cabo con el objetivo de agradecer a aquellos que forman parte del equipo de trabajo.</p>
INSERT INTO "blog" VALUES ('63', '<p>El mismo promueve el intercambio de conocimiento, experiencias y recursos con el objeto de mejorar el impacto de las acciones de ambas instituciones.</p>
INSERT INTO "blog" VALUES ('64', '<p>El objetivo es comenzar a trabajar en proyectos vinculados al desarrollo social, medioambiental, educacional, cultural y económico.</p>
INSERT INTO "blog" VALUES ('65', '<p>La titular del organismo presentó ante los legisladores porteños el proyecto de Ley de Presupuesto para el próximo año.</p>
INSERT INTO "blog" VALUES ('66', '<p>El mismo tiene como fin contribuir al desarrollo de tareas concretas en el marco del Programa de Prevención de la Violencia Laboral.</p>
INSERT INTO "blog" VALUES ('67', '<p>En la sesión ordinaria del pasado 13 de septiembre, la Legislatura había declarado de interés el trabajo realizado por la Editorial.</p>
INSERT INTO "blog" VALUES ('68', '<p>El acuerdo busca promover actividades que mejoren la atención de niños, niñas y adolescentes que transitan causas judiciales.</p>
INSERT INTO "blog" VALUES ('69', '<p>El encuentro tuvo como eje central la igualdad de género laboral y el acoso callejero.</p>
INSERT INTO "blog" VALUES ('70', '<p>El acuerdo busca promover la cooperación institucional en materia de capacitación y enseñanza.</p>
INSERT INTO "blog" VALUES ('71', '<p>La Dra. Marcela I. Basterra participó, como Consejera del Consejo de la Magistratura de la Ciudad Autónoma de Buenos Aires, de la charla en conjunto a la Secretaría de Coordinación de Políticas Judiciales sobre Acceso a la Justicia. La exposición se dio en el marco de la 42ª Feria Internacional del Libro de Buenos Aires el pasado lunes 9 de mayo en la Sala Alfonsina Storni.</p>
INSERT INTO "blog" VALUES ('72', '<p>El Congreso sobre “Derecho internacional de los Derechos Humanos. Protección procesal y constitucional” fue organizado por la Universidad de Buenos Aires y la Universidad Nacional Autónoma de México.</p>
INSERT INTO "blog" VALUES ('73', '<p>El reconocimiento contó con la participación de funcionarios que integran el fuero desde su constitución. Además, se reconoció la labor de los magistrados que desempeñan funciones desde los orígenes del mismo.</p>
INSERT INTO "blog" VALUES ('74', '<p>La presentación del “Protocolo de Intervención para el Acceso a Justicia de Mujeres en Situación de Violencia de Género en las relaciones de pareja” se llevó a cabo en las aulas del Centro de Formación Judicial.</p>
INSERT INTO "blog" VALUES ('75', '<p>Las actividades y reconocimientos se realizaron en el Salón de la Editorial Jusbaires.</p>
INSERT INTO "blog" VALUES ('76', '<p>El martes 13 de diciembre en el Salón Auditorio de Editorial Jusbaires, la Dra. Marcela I. Basterra presentó la publicación “Ciudad Transparente”, obra que dirigió y co-autora de la misma.</p>
INSERT INTO "blog" VALUES ('77', '<p>Estimados colegas, me despido de la presidencia del Consejo de la Magistratura de la CABA con un profundo agradecimiento especial por estos años de trabajo compartido y mucho respeto por todos los que me acompañaron: magistrados, funcionarios y empleados de la justicia porteña.</p>
INSERT INTO "blog" VALUES ('78', '<p>A partir del <strong>miércoles 5 de agosto</strong> inicia un nuevo seminario en el Centro de Formación Judicial sobre la responsabilidad del Estado. La Dra. Basterra estará a cargo de la Unidad I: “Bases constitucionales de la responsabilidad del Estado”.</p>
INSERT INTO "blog" VALUES ('79', '<p>La Dra. Basterra participó de las Jornadas Internacionales sobre Problemas Actuales de la Responsabilidad del Estado en la Universidad UCES como representante del Consejo de la Magistratura de CABA.</p>
INSERT INTO "blog" VALUES ('80', '<p>La Dra. Basterra coordinará el Seminario “Derechos Humanos y Justicia Constitucional” organizado por el Departamento de Derecho Público I. El mismo se llevará a cabo en el salón Vélez Sarsfield de la Facultad de Derecho de la Universidad de Buenos Aires el día <strong>miércoles 26 de agosto a las 18hs</strong>. La entrada es libre y gratuita.</p>
INSERT INTO "blog" VALUES ('81', '<p>La regulación de la Información Pública / Clarín</p>', 'La regulación de la Información Pública / Clarín', 'blog/imported-81.jpg', '2016-04-05 18:47:49', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('82', '<p>I Observatorio Interamericano de Derechos Humanos. La protección de los derechos humanos. Un diálogo entre América y Europa</p>', 'I Observatorio Interamericano de Derechos Humanos. La protección de los derechos humanos. Un diálogo entre América y Europa', 'blog/imported-82.jpg', '2015-05-13 02:52:54', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('83', '<p>El 15 de abril se llevó a cabo el II Congreso Internacional y V Jornadas de Administración y Justicia de la Ciudad de Buenos Aires, organizado por <a href="http://www.dpicuantico.com/" target="_blank">DPI Cuántico</a>. La Dra. Basterra integró el panel Nº6: <strong><em>“El Estado Democrático frente a la Objeción Democrática. ¿Es posible articular ambas nociones?”</em></strong> junto a colegas como el Dr. Alejandro Salla Vía y el maestro Pedro Sagües.</p>
INSERT INTO "blog" VALUES ('84', '<p>La Dra. Basterra se presentó ayer en la Universidad del Salvador para ampliar la propuesta del primer Concurso Universitario: <em><strong>“El acceso a la Justicia”</strong></em>. El concurso surge desde la Secretaría de Coordinación de Políticas Judiciales, que depende a su vez de la Comisión de Fortalecimiento Institucional y Planificación Estratégica.</p>
INSERT INTO "blog" VALUES ('85', '<p>La Dra. Basterra dirigió una nueva publicación editada por Abeledo Perrot: “El Tratado sobre Amparo en el Derecho Federal y Constitucional Provincial” Tomo I y Tomo II. El libro analiza la acción de Amparo, garantía constitucional por la cual se defienden casi todos los Derechos Constitucionales.</p>
INSERT INTO "blog" VALUES ('86', '<p>Semana de la Discapacidad: “I Concurso Artístico Discapacidad y Derechos”</p>', 'Semana de la Discapacidad: “I Concurso Artístico Discapacidad y Derechos”', 'blog/imported-86.jpg', '2015-11-30 04:36:02', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('87', '<p>Representantes de los tres organismos adhirieron a un convenio para trabajar proyectos referidos a la problemática de la violencia en el ámbito del trabajo.</p>
INSERT INTO "blog" VALUES ('88', '<p>El Consejo de la Magistratura de la Ciudad Autónoma de Buenos Aires inició, junto a los voluntarios del Poder Judicial, las charlas que forman parte del <strong>Programa de Acceso Comunitario a la Justicia</strong>. El mismo fue presentado el 8 de junio con el fin de “llevar la Justicia al plano real”.</p>
INSERT INTO "blog" VALUES ('89', '<p>El propósito de las charlas es transmitir a los vecinos información sobre los derechos de los niños, niñas y adolescentes, cuestiones de género, de personas con discapacidad y adultos mayores, y debatir situaciones en las que estos derechos pueden ser vulnerados. De esta forma, recalcó la Dra. Basterra, el Consejo de la Magistratura de la CABA pretende <em>“sacar a la justicia –y a las personas que la representan– del escritorio, cruzar el expediente y acercarse a donde vive la gente para aportar a la comunidad”</em>.</p>', 'El propósito de las charlas es transmitir a los vecinos información sobre los derechos de los niños, niñas y adolescentes, cuestiones de género, de personas con discapacidad y adultos mayores, y debatir situaciones en las que estos derechos pueden ser vulnerados. De esta forma, recalcó la Dra. Basterra, el Consejo de la Magistratura de la CABA pretende “sacar a la justicia –y a las personas que la representan– del escritorio, cruzar el expediente y acercarse a donde vive la gente para aportar a ', 'blog/imported-89.jpg', '2015-06-08 05:46:46', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('90', '<p>“A mayores niveles de transparencia, menor es la corrupción” / Caminando Buenos Aires</p>', '“A mayores niveles de transparencia, menor es la corrupción” / Caminando Buenos Aires', 'blog/imported-90.jpg', '2016-04-27 06:09:50', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('91', '<p>El lunes 27 de junio, durante el plenario de consejeros, se designaron a las nuevas autoridades del Consejo de la Magistratura de la Ciudad. La Dra. Marcela Basterra será la nueva Vicepresidenta del Consejo y aclaró: <em>“es un honor asumir el cargo”</em>. La Presidencia del Consejo de la Magistratura seguirá a cargo de Enzo Pagani.</p>
INSERT INTO "blog" VALUES ('92', '<p>“No debemos de justificar el interés legítimo a la hora de pedir información pública” / Contexto Político</p>', '“No debemos de justificar el interés legítimo a la hora de pedir información pública” / Contexto Político', 'blog/imported-92.jpg', '2016-04-12 19:19:04', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('93', '<p>Durante todos los días del 11 al 31 de julio se llevará a cabo la 26° Feria del Libro Infantil y Juvenil en el Centro Cultural Kirchner.</p>
INSERT INTO "blog" VALUES ('94', '<p>La Dra. Basterra integrará el Panel Académico que comienza el lunes a las 18.30hs junto a grandes especialistas del derecho Constitucional.</p>
INSERT INTO "blog" VALUES ('95', '<p>Acceso comunitario a la justicia como prioridad</p>', 'Acceso comunitario a la justicia como prioridad', 'blog/imported-95.jpg', '2016-08-10 19:13:18', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('96', '<p>Una necesaria reforma política / Clarín</p>', 'Una necesaria reforma política / Clarín', 'blog/imported-96.jpg', '2016-08-12 16:41:22', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('97', '<p>El martes 4 de octubre se cumplen 20 años de la Constitución de la Ciudad Autónoma de Buenos Aires que se sancionó el martes 1 de octubre de 1996. Con motivo de reflexión, se llevarán a cabo las Jornadas en conmemoración del traspaso de autonomía. En diversos paneles deliberativos sobre diferentes temáticas, participarán historiadores, políticos, consultores, ex-constituyentes, legisladores, juristas y catedráticos. Durante una extensa jornada se debatirá sobre la importancia histórica, política y social de la carta magna porteña.</p>
INSERT INTO "blog" VALUES ('98', '<p><strong>11.10.2016</strong></p>
INSERT INTO "blog" VALUES ('99', '<p>El equipo que lleva a cabo el Proyecto dentro del marco del Programa de Acceso Comunitario a la Justicia que impulsa el Consejo de la Magistratura produjo este corto documental sobre la actividad que inició en el 2016 y ya lleva alcanzados a más de 4 mil niños y niñas de la ciudad.</p>
INSERT INTO "blog" VALUES ('100', '<p>“Tenemos que empezar caminar el sendero de la Constitución” / La Dama y el Bárbaro</p>', '“Tenemos que empezar caminar el sendero de la Constitución” / La Dama y el Bárbaro', 'blog/imported-100.png', '2016-11-09 18:58:31', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('101', '<p>La Dra. Marcela I. Basterra fue invitada como Vicepresidenta del Consejo de la Magistratura a las Jornadas que dan apertura al “Segundo Plan Estratégico del Poder Judicial de Tierra del Fuego Juzgado — Dependencias Judiciales”, el pasado jueves 10 de noviembre.</p>
INSERT INTO "blog" VALUES ('102', '<p>El consejo de la Magistratura junto con la Facultad de Derecho y el Foro de Periodismo Argentino organizan estas jornadas enfocadas en el <em>Diálogo con la Justicia</em> el día jueves 24 de noviembre de 14 a 18h en el Salón Verde de Derecho (UBA).</p>
INSERT INTO "blog" VALUES ('103', '<p>El martes 1 de diciembre se reunieron en el Barrio de INTA (ex Villa 19) más de 60 mujeres, junto a sus hijas y sus hijos, para compartir una merienda en el marco del evento que le dio cierre al <strong>Programa de Acceso Comunitario a la Justicia</strong> del Consejo de la Magistratura de la Ciudad de Buenos Aires.</p>
INSERT INTO "blog" VALUES ('104', '<p>La Dra. Basterra, Vicepresidenta del Consejo de la Magistratura, y el Dr. Federico Penna del Centro de Estudios Jurídicos Latinoamericanos de la Universidad Tor Vergata de Roma, firmaron un convenio de marco de cooperación académica.</p>
INSERT INTO "blog" VALUES ('105', '<p>El <em><strong>Proyecto Teatro de Papel: Una función justa</strong></em> realizará un encuentro para dar cierre a las actividades de 2016. Luego de que más de 4.000 niños y niñas hayan disfrutado de las Funciones de <em>Teatro con Contenido de Derechos</em>, 100 de ell@s asistirán a un encuentro donde se llevará a cabo la presentación de “Derecho al cuento”. Cinco cuentos creados por chicos y chicas de la Ciudad de Buenos Aires de distintas organizaciones, junto a los artistas que encabezaron la actividad y los voluntarios del Poder Judicial, serán narrados promoviendo la perspectiva de derechos de infancia.</p>
INSERT INTO "blog" VALUES ('106', '<p>La semana de la discapacidad en la editorial jusbaires</p>', 'La semana de la discapacidad en la editorial jusbaires', 'blog/imported-106.jpg', '2016-12-06 01:49:55', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('107', '<p>El Consejo de la Magistratura de la Ciudad presenta el libro: “Constitución de la Ciudad Autónoma de la Ciudad Autónoma de Buenos Aires. Edición Comentada”, publicado por la Editorial Jusbaires, el <strong>lunes 19 de diciembre de 2016 a las 17h en el Salón Azul de la Facultad de Derecho de la UBA.</strong></p>
INSERT INTO "blog" VALUES ('108', '<p>La línea de trabajo que brinda “Charlas Orientadas a Derechos Humanos” y que forma parte del Programa de Acceso Comunitario a la Justicia celebró el cierre del 2016 con un encuentro el miércoles 7 de diciembre.</p>
INSERT INTO "blog" VALUES ('109', '<p>El Consejo de la Magistratura de la Ciudad presentó el libro <em><strong>Constitución de la Ciudad Autónoma de Buenos Aires. Edición Comentada</strong></em>, publicado por la Editorial Jusbaires, el lunes 19 de diciembre de 2016 a las 17h en el Salón Azul de la Facultad de Derecho de la UBA.</p>
INSERT INTO "blog" VALUES ('110', '<p>Violencia de Género y Derechos / Clarín</p>', 'Violencia de Género y Derechos / Clarín', 'blog/imported-110.jpg', '2016-12-27 20:33:04', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('111', '<p>Treinta voluntarios y voluntarias del Poder Judicial participaron del Programa de Acceso Comunitario a la Justicia durante el 2016, dando más de cien charlas sobre derechos en quince villas y barrios vulnerables de la Ciudad de Buenos Aires. Este es nuestro reconocimiento y agradecimiento a cada uno y a cada una de ell@s.</p>', 'Treinta voluntarios y voluntarias del Poder Judicial participaron del Programa de Acceso Comunitario a la Justicia durante el 2016, dando más de cien charlas sobre derechos en quince villas y barrios vulnerables de la Ciudad de Buenos Aires. Este es nuestro reconocimiento y agradecimiento a cada uno y a cada una de ell@s.', 'blog/imported-111.jpg', '2017-01-03 17:32:56', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('112', '<p>La línea Teatro de Papel –Una Función Justa– del Programa de Acceso Comunitario a la Justicia es una de las actividades que el Consejo de la Magistratura coordina en los barrios más vulnerables de la Ciudad de Buenos Aires para, en palabras de la Dra. Basterra, Vicepresidenta del Consejo, <em>“acercar la justicia a los barrios”.</em> El equipo que lleva adelante el proyecto está formado por 30 voluntarios y voluntarias del Poder Judicial y ya lleva alcanzados a más de 4 mil niños y niñas de la ciudad. En el día de ayer, comenzó su ciclo de teatro en la Villa 31.</p>
INSERT INTO "blog" VALUES ('113', '<p>Objeciones infundadas al traspaso de la Justicia / Clarín</p>', 'Objeciones infundadas al traspaso de la Justicia / Clarín', 'blog/imported-113.jpg', '2017-02-21 18:01:38', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('114', '<p>“Es un proyecto de ley con muy buenos estándares” / Universidad Crítica</p>', '“Es un proyecto de ley con muy buenos estándares” / Universidad Crítica', 'blog/imported-114.jpg', '2016-05-31 18:55:29', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('115', '<p>El miércoles 8 de marzo en el marco del Día Internacional de la Mujer, la Dra. Marcela Basterra, Vicepresidenta del Consejo de la Magistratura de CABA, participó de una Mesa Redonda de Mujeres invitada por la Dra. Adriana Donato, Presidenta del Consejo de la Magistratura de la Nación. En el encuentro se abordaron temas para seguir concientizando sobre la lucha de mujeres que hace años vienen trabajando por los derechos de género y de minorías.</p>
INSERT INTO "blog" VALUES ('116', '<p>El martes 14 de marzo la Dra. Marcela Basterra, Vicepresidenta del Consejo de la Magistratura CABA y la Consejera Vanesa Ferrazzuolo, participaron en un desayuno de trabajo organizado por la Lic. Silvina Pedreira de la Dirección de Relaciones con la Comunidad del Consejo. El encuentro propició un diálogo en el que se convocó a diferentes especialistas para hablar sobre la “incorporación de la perspectiva de género en los nuevos desafíos del Consejo de la Magistratura de la CABA”.</p>
INSERT INTO "blog" VALUES ('117', '<p>Este mes retomamos el Ciclo de Charlas sobre Derechos Humanos que forman parte del Programa de Acceso Comunitario a la Justicia del Consejo de la Magistratura de la Ciudad de Buenos Aires. La Vicepresidenta, Marcela I. Basterra, junto con la Unidad de Fortalecimiento Institucional y Planificación Estratégica dirigida por el Dr. Alejandro Fernández, impulsan este Programa que ya lleva brindadas 500 charlas y más de 170 obras de teatro “Una función justa” para niños/as de los barrios más vulnerables de la ciudad.</p>
INSERT INTO "blog" VALUES ('118', '<p><strong>Acceso a la Justicia / Traspaso de Competencias / Mesa de Debate sobre Derechos de Género</strong></p>
INSERT INTO "blog" VALUES ('119', '<p>conferencia sobre derechos de género y protección de las mujeres con expositores internacionales feria internacional del libro</p>', 'conferencia sobre derechos de género y protección de las mujeres con expositores internacionales feria internacional del libro', 'blog/imported-119.jpg', '2017-05-03 20:16:12', '2026-07-21 18:27:59', '2026-07-21 18:56:10', '0');
INSERT INTO "blog" VALUES ('120', '<p>El jueves 4 de mayo en la Sala Victoria Ocampo de la Feria del Libro, la Dra. Marcela I. Basterra junto a otras autoridades del Consejo de la Magistratura de la Ciudad y de la Editorial Jusbaires, presentó la obra “Transferencia de la Justicia Penal Ordinaria en el Proceso de Autonomía de la CABA”.</p>
INSERT INTO "blog" VALUES ('121', '<p>El viernes 12 de mayo la Doctora Marcela I. Basterra participó del panel institucional que dio apertura a la Jornada “Dialogando BA, Acceso a la Información”.</p>
INSERT INTO "blog" VALUES ('122', '<p>A través del <em>Programa de Acceso Comunitario a la Justicia</em> y en el marco de la 43<sup>a</sup> Feria Internacional del Libro se llevaron a cabo diferentes actividades para seguir acercando la Justicia a todas las personas que visitaban el predio.</p>
INSERT INTO "blog" VALUES ('123', '<p>El martes 9 de mayo en el Salón Domingo Faustino Sarmiento de la Feria Internacional del Libro, se llevó a cabo una Jornada sobre Derechos de Género con cuatro referentes en la temática, que plantearon temas centrales en torno a focos como: minorías, autonomía personal y discriminación.</p>
INSERT INTO "blog" VALUES ('124', '<p>“Durante el Kirchnerismo los jueces no investigaron ninguna denuncia en tiempo real” / Infobae</p>', '“Durante el Kirchnerismo los jueces no investigaron ninguna denuncia en tiempo real” / Infobae', 'blog/imported-124.jpg', '2017-06-12 16:47:55', '2026-07-21 18:27:59', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('125', '<p>Entrevista originalmente publicada en <a href="http://www.noticiasurbanas.com.ar/?noticia=voy-a-continuar-la-labor-de-enzo-sumandole-mi-sello-personal" target="_blank">noticiasurbanas.com.ar</a></p>
INSERT INTO "blog" VALUES ('126', '<p>La Dra. Marcela I. Basterra, Presidenta del Consejo de la Magistratura CABA, es una reconocida expositora internacional en materia de de Derecho Constitucional y Humanos. El pasado 9 de junio participó del panel “Los Instrumentos Jurídicos e Institucionales de Lucha contra la Corrupción”.</p>
INSERT INTO "blog" VALUES ('127', '<p>El martes 27 de junio en la Biblioteca de la Legislatura Porteña, la Presidenta del Consejo, la Dra. Marcela I. Basterra, estuvo a cargo de la conferencia de apertura de la Jornada “Poder Judicial y Justicia Transicional” organizada por el Consejo de la Magistratura de la CABA en conjunto con el Parlamento local.</p>
INSERT INTO "blog" VALUES ('128', '<p>Condenas femicidas y violencia contra la mujer / Clarín</p>', 'Condenas femicidas y violencia contra la mujer / Clarín', 'blog/imported-128.jpg', '2017-07-17 16:31:48', '2026-07-21 18:27:59', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('129', '<p>El miércoles 5 de julio el Consejo de la Magistratura de la Ciudad de Buenos Aires homenajeó a la Dra. Mabel Bianco por su trayectoria en la lucha por la igualdad de Derechos para las Mujeres en Latinoamérica.</p>
INSERT INTO "blog" VALUES ('130', '<p>Inauguración Posgrado Derechos Políticos y Electorales, Facultad de Derecho</p>', 'Inauguración Posgrado Derechos Políticos y Electorales, Facultad de Derecho', 'blog/imported-130.jpg', '2017-07-17 18:44:57', '2026-07-21 18:27:59', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('131', '<p>El Consejo de la Magistratura de la CABA firmó un Convenio con el Ministerio de Seguridad de la Nación para agilizar los procesos para la búsqueda de personas desaparecidas y extraviadas.</p>
INSERT INTO "blog" VALUES ('132', '<p>Durante el 2017, ya se dieron más de 70 charlas sobre Derechos Humanos en barrios noticias</p>', 'Durante el 2017, ya se dieron más de 70 charlas sobre Derechos Humanos en barrios noticias', 'blog/imported-132.jpg', '2017-07-27 16:42:50', '2026-07-21 18:27:59', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('133', '<p>Argentina presentó el 3er Plan de Acción de Gobierno Abierto</p>', 'Argentina presentó el 3er Plan de Acción de Gobierno Abierto', 'blog/imported-133.jpg', '2017-07-31 20:14:50', '2026-07-21 18:27:59', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('134', '<p>En el marco de la semana de la lactancia, se inauguró un nuevo lactario en el noveno piso del Consejo de la Magistratura de la Ciudad de Buenos Aires.</p>', 'En el marco de la semana de la lactancia, se inauguró un nuevo lactario en el noveno piso del Consejo de la Magistratura de la Ciudad de Buenos Aires.', 'blog/imported-134.jpg', '2017-08-08 17:16:57', '2026-07-21 18:27:59', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('135', '<p>Peligroso retroceso de la libertad en Internet / Clarín</p>', 'Peligroso retroceso de la libertad en Internet / Clarín', 'blog/imported-135.jpg', '2015-08-06 21:20:20', '2026-07-21 18:27:59', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('136', '<p>El miércoles 2 de agosto en la Sala de Plenario del Consejo de la Magistratura de la Ciudad Autónoma de Buenos Aires, las autoridades máximas de la justicia porteña formalizaron el reconocimiento al fallecido Dr. Enzo Pagani, con el descubrimiento de una placa conmemorativa que lleva su nombre en el recinto.</p>
INSERT INTO "blog" VALUES ('137', '<p>El jueves 3 de agosto, la Dra. Marcela I. Basterra participó de la apertura de las III Jornadas Internacionales de Justicia Penal Juvenil: La interdisciplina como herramienta judicial, organizadas entre el Centro de Formación Judicial y la Oficina de Apoyo a la Justicia Penal Juvenil del Consejo de la Magistratura.</p>
INSERT INTO "blog" VALUES ('138', '<p>El martes 8 de agosto la Presidenta del Consejo de la Magistratura de la CABA, la Dra. Marcela I. Basterra y el Presidente de la DAIA, Ariel Cohen Sabban, suscribieron un Convenio Marco de Colaboración para coordinar la puesta en marcha del “Programa Convivencia”.</p>', 'El martes 8 de agosto la Presidenta del Consejo de la Magistratura de la CABA, la Dra. Marcela I. Basterra y el Presidente de la DAIA, Ariel Cohen Sabban, suscribieron un Convenio Marco de Colaboración para coordinar la puesta en marcha del “Programa Convivencia”.', 'blog/imported-138.jpg', '2017-08-11 23:00:41', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('139', '<p>La Dra. Marcela I. Basterra participó de la actividad que fue organizada por la Municipalidad de Campana en conjunto con DPI Cuántico y tuvo como temática principal la Modernización e Innovación del Estado para la Defensa del Interés Público.</p>', 'La Dra. Marcela I. Basterra participó de la actividad que fue organizada por la Municipalidad de Campana en conjunto con DPI Cuántico y tuvo como temática principal la Modernización e Innovación del Estado para la Defensa del Interés Público.', 'blog/imported-139.jpg', '2017-08-11 23:33:06', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('140', '<p>Venezuela: un llamado urgente a restituir la democracia / Clarín</p>', 'Venezuela: un llamado urgente a restituir la democracia / Clarín', 'blog/imported-140.jpg', '2017-08-17 15:50:36', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('141', '<p>El miércoles 16 de agosto se llevó a cabo un evento de reconocimiento a aquellos voluntarios que participan del Programa de Acceso Comunitario a la Justicia que impulsa la Dra. Marcela I. Basterra desde la Presidencia del Consejo de la Magistratura.</p>', 'El miércoles 16 de agosto se llevó a cabo un evento de reconocimiento a aquellos voluntarios que participan del Programa de Acceso Comunitario a la Justicia que impulsa la Dra. Marcela I. Basterra desde la Presidencia del Consejo de la Magistratura.', 'blog/imported-141.jpg', '2017-08-24 17:49:20', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('142', '<p>El Consejo de la Magistratura de la Ciudad firmó un convenio específico de colaboración con el Ministerio de Educación de la CABA que promueve el trabajo en conjunto para fomentar el conocimiento de los derechos entre los alumnos de las escuelas porteñas.</p>
INSERT INTO "blog" VALUES ('143', '<p>Los alumnos de primer año de la Facultad de Derecho de la Universidad Católica de Buenos Aires recorrieron la sede del Consejo de la Magistratura y de la Editorial Jusbaires.</p>
INSERT INTO "blog" VALUES ('144', '<p>El Consejo de la Magistratura de la Ciudad continua impulsando el Plan <em>FinEs</em> que promueve que los empleados del Poder Judicial puedan continuar sus estudios primarios y/o secundarios, con la inauguración de una sede de estudios y una entrega de diplomas de los últimos egresados del programa.</p>
INSERT INTO "blog" VALUES ('145', '<p>La Comisión de Transferencia presidida por el consejero Darío Reynoso organizó esta jornada para analizar los 10 años de la implementación del Primer Código Procesal Penal.</p>', 'La Comisión de Transferencia presidida por el consejero Darío Reynoso organizó esta jornada para analizar los 10 años de la implementación del Primer Código Procesal Penal.', 'blog/imported-145.jpg', '2017-09-04 21:53:47', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('146', '<p>Charile Hebdo: Libertad de Expresión y Fundamentalismos / El Cronista</p>', 'Charile Hebdo: Libertad de Expresión y Fundamentalismos / El Cronista', 'blog/imported-146.jpg', '2015-07-07 21:36:56', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('147', '<p><em>“Empecemos a capacitar para que la sociedad se concientice en remover los obstáculos para el efectivo cumplimiento de los derechos”,</em> afirmó la Dra. Marcela I. Basterra en su encuentro con Nicolás Stupenengo, empleado del Consejo de la Magistratura y voluntario del Programa de Acceso Comunitario a la Justicia.</p>', '“Empecemos a capacitar para que la sociedad se concientice en remover los obstáculos para el efectivo cumplimiento de los derechos”, afirmó la Dra. Marcela I. Basterra en su encuentro con Nicolás Stupenengo, empleado del Consejo de la Magistratura y voluntario del Programa de Acceso Comunitario a la Justicia.', 'blog/imported-147.jpg', '2017-09-04 22:13:59', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('148', '<p>El miércoles 30 de agosto el equipo del Programa de Acceso Comunitario a la Justicia realizó una jornada de actividades dedicadas a los niños y niñas que viven en la villa 31. El evento se llevó a cabo con 15 voluntarios del Programa y contó con la participación de alrededor de 200 menores que se acercaron a celebrar el mes del niño junto a sus padres.</p>', 'El miércoles 30 de agosto el equipo del Programa de Acceso Comunitario a la Justicia realizó una jornada de actividades dedicadas a los niños y niñas que viven en la villa 31. El evento se llevó a cabo con 15 voluntarios del Programa y contó con la participación de alrededor de 200 menores que se acercaron a celebrar el mes del niño junto a sus padres.', 'blog/imported-148.jpg', '2017-09-04 22:40:01', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('149', '<p>En el marco del Día del Abogado el Consejo de la Magistratura y la Dra. Basterra agasajaron a los abogados y abogadas con un brindis.</p>
INSERT INTO "blog" VALUES ('150', '<p>La Dra. Marcela I. Basterra, como Presidenta del Consejo de la Magistratura de la CABA, firmó un convenio con la Escuela Superior de Estudios Jurídicos de la Universidad de Bolonia.</p>
INSERT INTO "blog" VALUES ('151', '<p>Entró en vigencia la nueva Ley 27.275 de Acceso a la Información Pública y, finalmente, Argentina se suma a los países que apuestan a los principios de máxima divulgación y transparencia, adscribiendo a una regla de oro del Estado de derecho que establece: “a mayores niveles de transparencia, menores niveles de corrupción”.</p>
INSERT INTO "blog" VALUES ('152', '<p>La Dra. Marcela I. Basterra visitó el centro Ositos Cariñosos en el Barrio Inta en el marco del Programa de Acceso Comunitario a la Justicia que impulsa desde el Consejo de la Magistratura.</p>
INSERT INTO "blog" VALUES ('153', '<p>La Dra. Marcela I. Basterra participó de la presentación del nuevo Sistema de Datos de la Justicia Argentina y de la que participó el Ministro de Justicia, Germán Garavano.</p>
INSERT INTO "blog" VALUES ('154', '<p>El “derecho a saber” fortalece la democracia / Clarín</p>', 'El “derecho a saber” fortalece la democracia / Clarín', 'blog/imported-154.jpg', '2017-10-17 18:12:50', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('155', '<p>El acuerdo entre ambas instituciones favorecerá la realización de programas de cooperación mutua entre el Consejo de la Magistratura CABA y la Procuración General ante la Suprema Corte de la Provincia de Buenos Aires.</p>
INSERT INTO "blog" VALUES ('156', '<p>La Dra. Marcela I. Basterra ofreció una charla sobre la Edición Comentada de la Constitución de la Ciudad que se editó con motivo de los 20 años desde que fue sancionada.</p>
INSERT INTO "blog" VALUES ('157', '<p>“Lo excepcional se convirtió en habitualidad y tenemos 300 jueces subrrogantes” / Cuento Chino</p>', '“Lo excepcional se convirtió en habitualidad y tenemos 300 jueces subrrogantes” / Cuento Chino', 'blog/imported-157.jpg', '2015-07-02 21:46:54', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('158', '<p>La Dra. Marcela I. Basterra firmó un convenio con el CIOBA (Centro de Información de las Organizaciones de la Ciudad de Buenos Aires) que apunta al mejoramiento de los registros de las ONGs de la Ciudad.</p>
INSERT INTO "blog" VALUES ('159', '<p>Marcela Basterra: “Estamos preparados para el traspaso” / Revista Comunas</p>', 'Marcela Basterra: “Estamos preparados para el traspaso” / Revista Comunas', 'blog/imported-159.jpg', '2017-11-06 17:29:34', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('160', '<p>Nuevo libro sobre Acceso a la Información Pública y Transparencia, Ley 27.275</p>', 'Nuevo libro sobre Acceso a la Información Pública y Transparencia, Ley 27.275', 'blog/imported-160.jpg', '2017-12-10 22:38:10', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('161', '<p>La Dra. Marcela I. Basterra viajó a la Ciudad de México en una visita oficial en representación del Consejo de la Magistratura de la CABA que tuvo como finalidad principal la concreción de diversas actividades en pos de estrechar vínculos con las instituciones judiciales de ese país. La delegación estuvo integrada por la consejera Vanesa Ferrazzuolo y la Secretaria de Asuntos Institucionales, Ana Casal.</p>
INSERT INTO "blog" VALUES ('162', '<p>Nuevo inmueble para el Poder Judicial CABA</p>', 'Nuevo inmueble para el Poder Judicial CABA', 'blog/imported-162.jpg', '2017-11-24 10:41:03', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('163', '<p>La Dra. Marcela I. Basterra expuso el Presupuesto 2018 en la Legislatura porteña.</p>
INSERT INTO "blog" VALUES ('164', '<p>En la inauguración de la muestra de Arte Correo contra la Violencia hacia a las Mujeres y Niñas se presentó el Nuevo Plan Senda –de Justicia y Mujeres en Situación de Violencia– y se firmó un convenio de colaboración con el INADI.</p>
INSERT INTO "blog" VALUES ('165', '<p>El evento que cerró las actividades de la línea de Infancia del programa que coordina la nueva Dirección de Acceso Comunitario a la Justicia reunió a más de 100 chicos en el Centro Cultural Recoleta.</p>
INSERT INTO "blog" VALUES ('166', '<p>El evento se realizó en la Corte Suprema de Justicia de la Nación y reunió a representantes de todas las provincias del país.</p>
INSERT INTO "blog" VALUES ('167', '<p>La Dra. Marcela I. Basterra junto a funcionarios del ámbito de la Nación y de la Ciudad pertenecientes a diversos organismos, plantearon desafíos y oportunidades de la transferencia de competencias judiciales en materia penal, de consumo, Inspección General de Justicia y Registro de la Propiedad Inmueble.</p>
INSERT INTO "blog" VALUES ('168', '<p>Marcela I. Basterra en Conversaciones desde la Cátedra / Radio UBA</p>', 'Marcela I. Basterra en Conversaciones desde la Cátedra / Radio UBA', 'blog/imported-168.jpg', '2018-05-28 16:05:19', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('169', '<p>¿Cada uno de nosotros va a poder usar la Ley de Acceso a la Información? / Mar de Noticias</p>', '¿Cada uno de nosotros va a poder usar la Ley de Acceso a la Información? / Mar de Noticias', 'blog/imported-169.jpg', '2016-05-08 20:56:38', '2026-07-21 18:28:00', '2026-07-21 18:56:11', '0');
INSERT INTO "blog" VALUES ('174', '<p>Una guia rapida para cargar paginas, bloques y enlaces internos. Este contenido fue creado por el seeder para validar el flujo de crear, editar, publicar y borrar novedades desde Filament.</p>', '<p>Una guia rapida para cargar paginas, bloques y enlaces internos.</p>', NULL, NULL, '2026-07-21 20:37:23', '2026-07-21 20:37:23', '0');
