INSERT INTO "blog" VALUES ('176', '<p>Que revisar antes de pasar una pagina o novedad a publicado. Este contenido fue creado por el seeder para validar el flujo de crear, editar, publicar y borrar novedades desde Filament.</p>', '<p>Que revisar antes de pasar una pagina o novedad a publicado.</p>', NULL, NULL, '2026-07-21 20:37:23', '2026-07-21 20:37:23', '0');
INSERT INTO "blog" VALUES ('177', '<p>Un repaso de los componentes genericos incluidos en el builder. Este contenido fue creado por el seeder para validar el flujo de crear, editar, publicar y borrar novedades desde Filament.</p>', '<p>Un repaso de los componentes genericos incluidos en el builder.</p>', NULL, NULL, '2026-07-21 20:37:23', '2026-07-21 20:37:23', '0');
