INSERT INTO "pages" VALUES ('1', 'Home', '[{"type":"Hero","data":{"blockTitle":"Hero \u00b7 Apertura editorial","blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"variant":"editorial","profile_photo":null,"image_alt":"","badge":"Derecho constitucional \u00b7 Universidad de Buenos Aires","name":"Marcela I. Basterra","subtitle":"Profesora Titular de Derecho Constitucional de la Facultad de Derecho, Universidad de Buenos Aires.","description":"","indicators":[{"label":"Derecho constitucional"},{"label":"Actividad acad\u00e9mica"}],"featured_positions":[1,2],"cta_primary":{"btn_label":"CV","route_id":"2","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false},"cta_secondary":{"btn_label":"Ver publicaciones","route_id":"6","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false},"cta_tertiary":{"btn_label":"Actualidad","route_id":"14","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"BiographySummary","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Presentaci\u00f3n","summary":"<p>Doctora en Derecho (UBA), Profesora Titular de Derecho Constitucional de la Universidad de Buenos Aires y referente en derecho constitucional y procesal constitucional. Ha ocupado destacados cargos institucionales, dictado conferencias en numerosos pa\u00edses y es autora de m\u00e1s de 50 libros y un centenar de publicaciones especializadas. Su labor ha sido distinguida por la Legislatura de la Ciudad Aut\u00f3noma de Buenos Aires por su aporte a las Ciencias Jur\u00eddicas.<\/p>","photo":null,"cta_label":"Conocer trayectoria completa","cta_route":{"btn_label":null,"route_id":"2","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"PublicationsHighlight","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"\u00daltimo libro","description":"La publicaci\u00f3n m\u00e1s reciente de Marcela I. Basterra.","source_mode":"latest","libros":[],"articulos":[],"max_items":1,"show_type_label":true,"cta_label":"Ver todas las publicaciones","cta_route":{"btn_label":null,"route_id":"6","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"PressFeed","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Actualidad y publicaciones recientes","description":"Art\u00edculos, entrevistas y noticias en medios.","content_types":["articulo","entrevista","noticia"],"media":"","selected_items":[],"max_items":6,"show_filters":false,"show_image":true,"empty_message":"Pr\u00f3ximamente se incorporar\u00e1n nuevas publicaciones."}},{"type":"EventsListing","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Conferencias y exposiciones","description":"Intervenciones p\u00fablicas disponibles en YouTube y en la Facultad de Derecho de la UBA.","conferencias":[1,2,3,4,5,6],"manual_items":[]}},{"type":"CTA","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Invitaciones acad\u00e9micas, institucionales y de prensa","text":"Para conferencias, entrevistas, actividades acad\u00e9micas y colaboraciones institucionales.","button_label":"Ponerse en contacto","button_route":{"btn_label":null,"route_id":"3","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}}]', '2026-06-10 17:41:29', '2026-07-23 17:29:22');
INSERT INTO "pages" VALUES ('2', 'Sobre mí', '[{"type":"BiographySummary","data":{"blockTitle":null,"blockAnchor":"biografia","mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Sobre m\u00ed","heading_level":"h1","summary":"<p>Doctora en Derecho (UBA) y Mag\u00edster en Derecho Constitucional y Derechos Humanos (UP). Presidenta de la Asociaci\u00f3n Argentina de Derecho Constitucional y Vicepresidenta de la Asociaci\u00f3n Argentina de Derecho Procesal Constitucional. Ex Presidenta del Consejo de la Magistratura de la Ciudad Aut\u00f3noma de Buenos Aires. Miembro del Instituto de Pol\u00edtica Constitucional de la Academia Nacional de Ciencias Morales y Pol\u00edticas y del Instituto de Derecho Constitucional de la Academia Nacional de Derecho y Ciencias Sociales.<\/p><p>Profesora Titular de Derecho Constitucional de la Universidad de Buenos Aires y profesora de grado, posgrado y doctorado en diversas universidades nacionales y extranjeras. Ha dictado clases y conferencias en Espa\u00f1a, Italia, Chile, Uruguay, Paraguay, Bolivia, Per\u00fa, Colombia, Guatemala, Estados Unidos y M\u00e9xico.<\/p><p>Co-Directora Acad\u00e9mica del Posgrado de Actualizaci\u00f3n en Derecho Constitucional y Procesal Constitucional (UBA). Es autora, coautora, directora y participante en 56 libros; ha publicado m\u00e1s de un centenar de art\u00edculos especializados y dictado m\u00e1s de un centenar de conferencias.<\/p>","photo":null,"cta_label":null,"cta_route":{"btn_label":null,"route_id":null,"external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"ContentList","data":{"blockTitle":null,"blockAnchor":"trayectoria-en-cifras","mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Trayectoria en cifras","description":"Una s\u00edntesis de la actividad acad\u00e9mica, editorial e institucional desarrollada a lo largo de su carrera.","variant":"metrics","source_mode":"manual","institutional_positions":[],"items":[{"meta":"56","title":"Libros publicados","text":"Como autora, coautora o directora.","url":null,"link_label":null},{"meta":"+100","title":"Art\u00edculos especializados","text":null,"url":null,"link_label":null},{"meta":"+100","title":"Conferencias","text":"Nacionales e internacionales.","url":null,"link_label":null},{"meta":"+10","title":"Universidades","text":"Nacionales e internacionales donde dicta clases.","url":null,"link_label":null},{"meta":"UBA","title":"Profesora Titular de Derecho Constitucional","text":null,"url":null,"link_label":null},{"meta":"Posgrado","title":"Co-Directora Acad\u00e9mica","text":"Actualizaci\u00f3n en Derecho Constitucional y Procesal Constitucional \u00b7 UBA.","url":null,"link_label":null}]}},{"type":"ContentList","data":{"blockTitle":null,"blockAnchor":"cargos","mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Responsabilidades institucionales actuales","description":"Funciones vigentes respaldadas por sus fuentes institucionales.","source_mode":"institutional_positions","institutional_positions":[1,2],"items":[]}},{"type":"MediaText","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"layout":"left","media_type":"youtube","youtube_id":"0QQH1t2nLWU","video_file":null,"image":null,"title":"Personalidad Destacada en Ciencias Jur\u00eddicas","content":"<p>La Legislatura de la Ciudad Aut\u00f3noma de Buenos Aires declar\u00f3 a la Dra. Marcela I. Basterra Personalidad Destacada de la Cultura en el \u00e1mbito de las Ciencias Jur\u00eddicas (Expte. 1774-D-2022).<\/p>","cta":{"btn_label":null,"route_id":null,"external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"CVAccess","data":{"blockTitle":null,"blockAnchor":"cv","mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Curr\u00edculum vitae","description":"Trayectoria acad\u00e9mica, institucional y profesional en dos versiones de consulta.","documents":[]}}]', '2026-06-10 17:41:29', '2026-07-22 18:41:42');
