INSERT INTO "pages" VALUES ('17', 'Muestra de bloques', '[{"type":"Hero","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"profile_photo":null,"badge":"Muestra de dise\u00f1o","name":"Marcela Basterra","subtitle":"Abogada constitucionalista, acad\u00e9mica e investigadora","description":"Una p\u00e1gina de demostraci\u00f3n con contenido ficticio para validar los 17 bloques registrados del CMS.","indicators":[{"label":"25 a\u00f1os de trayectoria"},{"label":"120 publicaciones"},{"label":"45 conferencias"}],"cta_primary":{"btn_label":"Ver trayectoria","route_id":"11","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false},"cta_secondary":{"btn_label":"Ver publicaciones","route_id":"6","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false},"cta_tertiary":{"btn_label":"Actualidad y medios","route_id":"14","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"BiographySummary","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Una mirada sobre el derecho constitucional","summary":"<p>Este texto es ficticio y representa un resumen biogr\u00e1fico editable desde el CMS. Aqu\u00ed podr\u00eda presentarse la trayectoria, las \u00e1reas de especializaci\u00f3n y la perspectiva profesional.<\/p>","photo":null,"cta_label":"Conocer trayectoria","cta_route":{"btn_label":null,"route_id":"2","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"BookPresentation","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"intro_title":"Libros y pensamiento","intro_description":"Una selecci\u00f3n ficticia de publicaciones para probar la presentaci\u00f3n editorial.","items":[{"title":"Constituci\u00f3n y democracia","description":"Ensayo ficticio sobre instituciones y ciudadan\u00eda.","image":null},{"title":"Derechos en movimiento","description":"Investigaci\u00f3n ficticia sobre derechos humanos.","image":null},{"title":"La palabra p\u00fablica","description":"Compilaci\u00f3n ficticia de conferencias y entrevistas.","image":null}]}},{"type":"CTA","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"\u00bfQuer\u00e9s conocer m\u00e1s?","text":"Este es un llamado a la acci\u00f3n de ejemplo para invitaciones, consultas y colaboraciones.","button_label":"Ir a contacto","button_route":{"btn_label":null,"route_id":"3","external_url":null,"file":null,"download_name":null,"anchor":null,"new_window":false}}},{"type":"CVDownload","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Trayectoria completa","description":"Descarg\u00e1 una versi\u00f3n ficticia del curriculum vitae para probar este bloque.","button_text":"Descargar CV de muestra"}},{"type":"Cards","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"\u00c1reas de trabajo","description":"<p>Tarjetas ficticias para representar distintos ejes de actividad.<\/p>","items":[{"label":"articulo","title":"Derecho constitucional","description":"An\u00e1lisis de instituciones y garant\u00edas.","image":null,"route":[]},{"label":"entrevista","title":"Debate p\u00fablico","description":"Participaci\u00f3n en conversaciones de actualidad.","image":null,"route":[]},{"label":"libro","title":"Investigaci\u00f3n acad\u00e9mica","description":"Producci\u00f3n y divulgaci\u00f3n de conocimiento.","image":null,"route":[]}]}},{"type":"ContactForm","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Escribinos","description":"Formulario ficticio para consultas generales y propuestas de colaboraci\u00f3n.","recipient_email":"muestra@example.com","success_message":"Mensaje de muestra enviado correctamente.","show_phone":true,"show_subject":true}},{"type":"EventsHighlight","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Pr\u00f3ximas actividades","description":"El bloque mostrar\u00e1 eventos seleccionados cuando existan registros disponibles.","eventos":[],"max_items":3,"show_past":false}},{"type":"FeaturedResources","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Recursos destacados","description":"Selecci\u00f3n ficticia de recursos relacionados.","items":[]}},{"type":"InterviewsHighlight","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"En los medios","description":"Entrevistas ficticias destacadas para probar el listado.","entrevistas":[],"max_items":3}},{"type":"Media","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"media_type":"image","youtube_id":null,"video_file":null,"image":null,"caption":"Imagen de muestra para el bloque multimedia."}},{"type":"MediaText","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"layout":"left","media_type":"image","youtube_id":null,"video_file":null,"image":null,"title":"Imagen y argumento","content":"<p>Contenido ficticio para validar la convivencia entre una pieza multimedia y un texto editorial.<\/p>","cta":[]}},{"type":"PublicationsHighlight","data":{"blockTitle":null,"blockAnchor":null,"mb":"mb-12","mdMb":"md:mb-0","clases":[],"styles":[],"stylesMd":[],"hidden":false,"title":"Publicaciones destacadas","d