INSERT INTO "publicaciones_medios" VALUES ('1', 'articulo', 'La Política Online', '2018-07-02 00:00:00', '<p>24.06.2018 Medio: La Política Online “Llega un momento que el traspaso se va a dar”, asegura Marcela Basterra, titular del Consejo de la Magistratura porteño. La referencia es a la transferencia de competencias desde la Nación hacia la Ciudad, pero también hacia los jueces que rechazan pasar a la órbita capitalina. “Muchos jueces nacionales por su propia historia se quieren jubilar en el mismo lugar. Hay resistencia...</p>', 'http://www.lapoliticaonline.com/nota/113688/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('2', 'articulo', 'Medios', '2018-06-29 00:00:00', '<p>28.06.2018 Medio: Infobae El 28 de junio se cumplen 48 años (casi medio siglo) de los disturbios producidos en 1969 en Stonewall, Estados Unidos, que marcaron el inicio del denominado movimiento de liberación homosexual. Resulta oportuno reflexionar sobre el camino que se ha recorrido en pos del respeto a la identidad y la diversidad de género y analizar cuáles son las realidades que actualmente impactan al colectivo...</p>', 'https://www.infobae.com/opinion/2018/06/28/dia-del-orgullo-gay-por-que-la-igualdad-formal-es-insuficiente/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('3', 'entrevista', 'Radio UBA', '2018-05-28 00:00:00', '<p>23.05.2018 Audio: Entrevista completa Error occurred when trying to fetch the file using wp_safe_remote_get(). Response could not be parsed</p>', 'http://www.uba.ar/radio/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('4', 'articulo', 'Revista El Cronista', '2018-05-01 00:00:00', '<p>06.11.2017 Revista: Gobiernos &amp; Intendencias http://marcelabasterra.com.ar/wp-content/uploads/2018/05/Gob-09032018.pdf</p>', 'https://marcelabasterra.com.ar/la-mujer-y-el-servicio-de-justicia-revista-el-cronista/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('5', 'articulo', 'Urgente 24', '2018-03-22 00:00:00', '<p>06.11.2017 Medio: Urgente 24 Resultan innegables las numerosas transformaciones sociales y culturales de las últimas décadas, que han exigido una adaptación y modernización de los poderes del Estado, a fin de dar adecuada respuesta a las nuevas y cambiantes necesidades de los ciudadanos. Las principales funciones del Poder Judicial, han sido y seguirán siendo garantizar el acceso a la justicia y a una tutela judicial...</p>', 'https://www.urgente24.com/275332-una-necesaria-y-ambiciosa-reforma-judicial', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('6', 'articulo', 'Revista Pensar Jusbaires', '2018-02-27 00:00:00', '<p>06.11.2017 Revista: Pensar Jusbaires http://marcelabasterra.com.ar/wp-content/uploads/2018/02/014_pensar_06-nov-2017_.pdf</p>', 'https://marcelabasterra.com.ar/reflexiones-breves-sobre-los-veinte-anos-de-la-justicia-portena-revista-pensar-jusbaires/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('7', 'articulo', 'Revista Entre Todos Ciudad', '2018-01-28 00:00:00', '<p>06.11.2017 Revista: Entre Todos Ciudad http://marcelabasterra.com.ar/wp-content/uploads/2018/02/Entre-todos-Ciudad.pdf</p>', 'https://marcelabasterra.com.ar/avances-y-desafios-revista-entre-todos-ciudad/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('8', 'articulo', 'Revista Comunas', '2017-11-06 00:00:00', '<p>10.06.2017 Entrevista: Rodrigo Marcogliese —No recuerdo un Presidente del Consejo de la Magistratura de la Ciudad que no haya ingresado desde la Legislatura… Yo accedo al Consejo en representación de los abogados. Integré la fórmula en la que ingresamos dos abogados por la mayoría, y además, uno entró por la minoría. Es verdad que para llegar a estos lugares normalmente se necesita de un empuje político, pero es tan...</p>', 'http://www.agenciacomunas.com.ar/marcela-basterra-estamos-preparados-para-el-traspaso/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('9', 'articulo', 'Clarín', '2017-10-17 00:00:00', '<p>09.10.2017 Por: Marcela I. Basterra El 28 de septiembre pasado se celebró el Día Mundial del Acceso a la Información Pública, fecha que también es conocida como el Día Internacional del derecho a saber, y que fue establecida en la Ciudad de Sofía, Bulgaria, en el año 2002. En tal oportunidad, se reunieron distintas organizaciones con el fin de crear una red de promotores en pos de la generación de gobiernos más trans...</p>', 'https://www.clarin.com/opinion/derecho-saber-fortalece-democracia_0_ryzc30IhW.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('10', 'articulo', 'Clarín', '2017-08-17 00:00:00', '<p>17.08.2017 Por: Marcela I. Basterra Más de 120 muertos en cuatro meses de protestas, niveles de violencia nunca antes vivenciados y una crisis económica, política, social y humanitaria sin precedentes son la triste consecuencia de la vulneración constante del orden constitucional y los derechos humanos en Venezuela. El pasado domingo 30 de julio tuvo lugar la votación, cuestionada por fraudulenta, para elegir la conf...</p>', 'https://www.clarin.com/opinion/venezuela-llamado-urgente-restituir-democracia_0_Sy66wHfd-.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('11', 'articulo', 'Clarín', '2017-07-17 00:00:00', '<p>28.06.2017 En los últimos días han sucedido dos hechos muy importantes en materia de violencia contra la mujer. En la provincia de Buenos Aires se llevó a cabo el primer juicio por jurados para este tipo de delitos. Claudia Schaefer fue asesinada por su ex marido Fernando Farré, quien fue declarado culpable por unanimidad y condenado a prisión perpetua por el delito de homicidio doblemente agravado por el vínculo y f...</p>', 'https://www.clarin.com/opinion/condenas-femicidas-violencia-mujer_0_HyoyYD27W.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('12', 'articulo', 'Medios', '2017-06-30 00:00:00', '<p>26.06.2017 La Dra. Basterra como Presidenta del Consejo recibió al medio en su oficina y adelantó los lineamientos de su gestión. Sostuvo la importancia del traspaso de la justicia y afirmó que “traerá una Justicia más rápida, cercana y moderna”. También habló de la inclusión de nuevas tecnologías y de los avances en materia de género, temas que para ella son fundamentales. Frase destacada: “Todo fue muy traumático p...</p>', 'http://www.noticiasurbanas.com.ar/?noticia=voy-a-continuar-la-labor-de-enzo-sumandole-mi-sello-personal', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('13', 'articulo', 'Infobae', '2017-06-12 00:00:00', '<p>10.06.2017 Entrevista: Silvia Mercado —Cuéntenos qué hace el Consejo de la Magistratura de la Ciudad. Es la autoridad que se encarga de seleccionar a los jueces y los elige la Legislatura. En la Ciudad los jueces los selecciona el Consejo de la Magistratura, pero no los elige el Jefe de Gobierno, sino la Legislatura. Nosotros tenemos la tarea de selección, la potestad disciplinaria y la potestad de la administración...</p>', 'https://www.infobae.com/politica/2017/06/10/durante-el-kirchnerismo-los-jueces-no-investigaron-ninguna-denuncia-en-tiempo-real/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('14', 'articulo', 'Clarín', '2017-02-21 00:00:00', '<p>Por: Marcela I. Basterra Ante las diversas críticas realizadas al denominado “traspaso de la Justicia nacional” a la órbita de la Ciudad Autónoma de Buenos Aires, y con el fin de aportar claridad a la ciudadanía -que presencia un debate teñido de notas constitucionales y una natural resistencia a los cambios-, es necesario aclarar algunos puntos. La transferencia de la “justicia nacional” no es un simple acuerdo entr...</p>', 'http://www.clarin.com/opinion/objeciones-infundadas-traspaso-justicia_0_Hy13IrfKe.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('15', 'articulo', 'Clarín', '2016-12-27 00:00:00', '<p>Por: Marcela I. Basterra Este mes, en que se celebró el Día Internacional de los Derechos Humanos, invita a reflexionar sobre la creciente violencia de género en nuestro país y en las sociedades más modernas. Las redes sociales y la velocidad de las comunicaciones permiten evidenciar esta problemática, otorgando visibilidad a un tema que hasta hace poco era “tabú”. El Comité para la Eliminación de la Discriminación c...</p>', 'http://www.clarin.com/opinion/Violencia-genero-derechos_0_BkW6ZJqEe.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('16', 'articulo', 'La Dama y el Bárbaro', '2016-11-09 00:00:00', '<p>Video: La Dra. Basterra hablando sobre la importancia de las leyes, la justicia y la constitución junto a Malú Kikuchi.</p>', 'https://marcelabasterra.com.ar/tenemos-que-empezar-caminar-el-sendero-de-la-constitucion/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('17', 'articulo', 'Clarín', '2016-08-12 00:00:00', '<p>Por: Marcela I. Basterra El sistema electoral argentino adoptado en 1912 no brinda soluciones adecuadas a los conflictos político-electorales de hoy. Hace tiempo que la Justicia, la sociedad civil, partidos políticos y ONG’s alertan sobre la necesidad de avanzar hacia un nuevo modelo electoral, que brinde seguridad, celeridad y transparencia a los procesos democráticos del siglo XXI. El engorroso sistema de boletas m...</p>', 'http://www.clarin.com/opinion/necesaria-reforma-politica_0_1630037138.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('18', 'articulo', 'Universidad Crítica', '2016-05-31 00:00:00', '<p>a Frases destacadas de la entrevista “Ahora, la Agencia Federal de Control va a hacer los controles, esto es que se puede pedir información ya sea por Internet o un pedido informal, y que se cumpla.” “En su momento había que explicar la motivación, y hoy hay innecesaridad de la información, no tenemos que explicar los ciudadanos para qué queremos la ley, sino que nos tiene que explicar a nosotros.” “Para la elección...</p>', 'http://tv.ub.edu.ar/2016_05_21.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('19', 'articulo', 'Mar de Noticias', '2016-05-08 00:00:00', '<p>a Frases destacadas de la entrevista “Vamos a poder pedirles información que nosotros como ciudadanos querramos conocer a los funcionarios públicos. El pedido se va a hacer ante el organismo requerido, por ejemplo, llámese PAMI, ANSES, Congreso, y el organismo requerido va a tener 15 días para contestar, y 15 días más como plazo, y sino lo hace automáticamente va a pasar al órgano de control que es la Agencia Federal...</p>', 'https://marcelabasterra.com.ar/cada-uno-de-nosotros-va-a-poder-usar-la-ley-de-acceso-a-la-informacion/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('20', 'articulo', 'Caminando Buenos Aires', '2016-04-27 00:00:00', '<p>Audio: La Dra. Basterra hablando sobre el Acceso a la Información Pública en el programa conducido por Daniel Gutman y Guillermo Kellmer
INSERT INTO "publicaciones_medios" VALUES ('21', 'articulo', 'Contexto Político', '2016-04-12 00:00:00', '<p>Audio: La Dra. Basterra hablando sobre el Acceso a la Información Pública en el programa conducido por Fernando Dotti
INSERT INTO "publicaciones_medios" VALUES ('22', 'articulo', 'Clarín', '2016-04-05 00:00:00', '<p>Por: Marcela I. Basterra Desde hace varios años venimos alertando sobre la necesidad de sancionar una ley de Transparencia y Acceso a la Información Pública. Lamentablemente, nuestro país es uno de los cuatro de Latinoamérica que no tiene una regulación específica en la materia. En consecuencia, seguimos muy mal ubicados en el ranking elaborado por Transparencia Internacional sobre percepción de corrupción, obteniend...</p>', 'http://www.clarin.com/opinion/regulacion-informacion-publica_0_1552045097.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('23', 'articulo', 'Clarín', '2015-09-29 00:00:00', '<p>Por: Marcela I. Basterra El Sistema Electoral Argentino adoptado en 1912 se correspondía con una coyuntura política e histórica compleja muy diferente a la actual. Dicho régimen no fue modificado en lo medular desde aquel entonces y, como es de esperar, en la actualidad ya no brinda respuesta a los conflictos y fenómenos político-electorales emergentes. Desde hace por lo menos diez años este sistema viene dando clara...</p>', 'http://www.clarin.com/opinion/Tucuman-Justicia-Democracia-Transparencia_0_1439856043.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:41', '2026-07-21 19:13:41');
INSERT INTO "publicaciones_medios" VALUES ('24', 'articulo', 'Clarín', '2015-08-06 00:00:00', '<p>Por: Marcela I. Basterra Recientemente en el ámbito del Congreso, la Comisión de Derechos Humanos y Garantías dictaminó a favor de un proyecto impulsado por legisladores oficialistas que propone ampliar la definición de acto discriminatorio extendiendo su alcance a Internet, fija penas de multa, clausura, perdida de concesiones, etc. Configura la responsabilidad de los administradores por expresiones vertidas por los...</p>', 'http://www.clarin.com/opinion/Censura-Libertad_de_Expresion-Constitucion_Nacional_0_1407459289.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:42', '2026-07-21 19:13:42');
INSERT INTO "publicaciones_medios" VALUES ('25', 'articulo', 'El Cronista', '2015-07-07 00:00:00', '<p>Por: Marcela I. Basterra A seis meses del atentado al semanario francés Charlie Hebdo, es importante considerar el contexto complejo en el que sucedió y preguntarnos cómo proceder cuando se trata de un enfrentamiento entre civilizaciones y culturas tan diferentes, sin llegar a someternos cediendo nuestra libertad. El día 7 de enero, dos terroristas irrumpieron en la redacción de la revista asesinando a quemarropa a d...</p>', 'http://www.cronista.com/columnistas/Charlie-Hebdo-puede-limitarse-la-libertad-de-expresion-20150707-0020.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:42', '2026-07-21 19:13:42');
INSERT INTO "publicaciones_medios" VALUES ('26', 'articulo', 'Cuento Chino', '2015-07-02 00:00:00', '<p>Audio: La Dra. Basterra hablando sobre subrrogancias en el programa de Carlos Kikuchi</p>', 'https://marcelabasterra.com.ar/lo-excepcional-se-convirtio-en-habitualidad-y-tenemos-300-jueces-subrrogantes/', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:42', '2026-07-21 19:13:42');
INSERT INTO "publicaciones_medios" VALUES ('27', 'articulo', 'Contexto Político', '2015-06-15 00:00:00', '<p>a Frases destacadas de la entrevista “La protección de datos personales resguarda los datos falsos y discriminatorios denominados datos sensibles.” “La ley Argentina y las buenas leyes de protección de datos personales del mundo protegen el Derecho a la intimidad y los datos que se pueden manejar sin problema, los denominados datos comunes.”</p>', 'https://www.youtube.com/watch?v=FpnORCEXFkU', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:42', '2026-07-21 19:13:42');
INSERT INTO "publicaciones_medios" VALUES ('28', 'articulo', 'Infobae', '2015-04-24 00:00:00', '<p>Por: Marcela I. Basterra Este 24 de abril se cumple el centenario del genocidio iniciado en la ciudad de Estambul en el que pueblo armenio sufrió la deportación forzosa y el exterminio de un número incalculable de civiles, estimado entre uno y dos millones. En 1915 se detuvo a cientos de miembros de la comunidad armenia; entre ellos, intelectuales, políticos, religiosos y artistas. A la detención, le siguieron marcha...</p>', 'https://www.infobae.com/2015/04/24/1724331-un-crimen-grabado-la-conciencia-universal', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:42', '2026-07-21 19:13:42');
INSERT INTO "publicaciones_medios" VALUES ('29', 'articulo', 'Sección Política', '2015-04-08 00:00:00', '<p>Por: Marcela I. Basterra El acceso a la información pública se vincula directamente con la publicidad de los actos de gobierno y el principio de transparencia de la administración. Es un instrumento indispensable del sistema republicano y democrático de gobierno. Se relaciona además, con el derecho de participación de los ciudadanos en la vida pública por la que decididamente opta el Estado constitucional de derecho....</p>', 'http://www.seccionpolitica.com.ar/por-que-una-ley-de-acceso-a-la-informacion-publica-did26840.html', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:42', '2026-07-21 19:13:42');
INSERT INTO "publicaciones_medios" VALUES ('30', 'articulo', 'Infobae', '2014-10-30 00:00:00', '<p>Por: Marcela I. Basterra En el contexto de los últimos años en que se han implementado una serie de restricciones a la libertad de expresión (manejo discrecional de la publicidad oficial, adecuación de oficio y aplicación compulsiva de la ley de medios, cepo publicitario, denegación de acceso a la información pública, etc.), resulta llamativo al menos, el proyecto de ley ingresado a la Cámara de Diputados referido a...</p>', 'https://www.infobae.com/2014/10/30/1605254-restricciones-que-podrian-obstaculizar-el-proceso-democratico', 'Marcela I. Basterra', NULL, '0', NULL, '2026-07-21 19:13:42', '2026-07-21 19:13:42');
