INSERT INTO "routes" VALUES ('237', 'II Congreso Internacional y V Jornadas de Administración y Justicia', 'ii-congreso-internacional-y-v-jornadas-de-administracion-y-justicia', 'published', 'App\Models\Blog', '83', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/ii-congreso-internacional-y-v-jornadas-de-administracion-y-justicia', '4', NULL, NULL, NULL, 'El 15 de abril se llevó a cabo el II Congreso Internacional y V Jornadas de Administración y Justicia de la Ciudad de Buenos Aires, organizado por DPI Cuántico. La Dra. Basterra integró el panel Nº6: “El Estado Democrático frente a la Objeción Democrática. ¿Es posible articular ambas nociones?” junto a colegas como el Dr. Alejandro Salla Vía y el maestro Pedro Sagües.', 'blog/imported-83.jpg');
INSERT INTO "routes" VALUES ('238', 'Ampliando el Acceso a la Justicia', 'ampliando-el-acceso-a-la-justicia', 'published', 'App\Models\Blog', '84', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/ampliando-el-acceso-a-la-justicia', '4', NULL, NULL, NULL, 'La Dra. Basterra se presentó ayer en la Universidad del Salvador para ampliar la propuesta del primer Concurso Universitario: “El acceso a la Justicia”. El concurso surge desde la Secretaría de Coordinación de Políticas Judiciales, que depende a su vez de la Comisión de Fortalecimiento Institucional y Planificación Estratégica.', 'blog/imported-84.jpg');
INSERT INTO "routes" VALUES ('239', 'Presentación de nuevo Tratado sobre Amparo', 'presentacion-de-nuevo-tratado-sobre-amparo', 'published', 'App\Models\Blog', '85', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/presentacion-de-nuevo-tratado-sobre-amparo', '4', NULL, NULL, NULL, 'La Dra. Basterra dirigió una nueva publicación editada por Abeledo Perrot: “El Tratado sobre Amparo en el Derecho Federal y Constitucional Provincial” Tomo I y Tomo II. El libro analiza la acción de Amparo, garantía constitucional por la cual se defienden casi todos los Derechos Constitucionales.', 'blog/imported-85.jpg');
INSERT INTO "routes" VALUES ('240', 'Semana de la Discapacidad: “I Concurso Artístico Discapacidad y Derechos”', 'semana-de-la-discapacidad-i-concurso-artistico-discapacidad-y-derechos', 'published', 'App\Models\Blog', '86', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/semana-de-la-discapacidad-i-concurso-artistico-discapacidad-y-derechos', '4', NULL, NULL, NULL, 'Semana de la Discapacidad: “I Concurso Artístico Discapacidad y Derechos”', 'blog/imported-86.jpg');
INSERT INTO "routes" VALUES ('241', 'El Consejo de la Magistratura de la Ciudad, la Defensoría del Pueblo y el Observatorio de Género impulsan proyectos contra la violencia laboral', 'el-consejo-de-la-magistratura-de-la-ciudad-la-defensoria-del-pueblo-y-el-observatorio-de-genero-impulsan-proyectos-contra-la-violencia-laboral', 'published', 'App\Models\Blog', '87', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/el-consejo-de-la-magistratura-de-la-ciudad-la-defensoria-del-pueblo-y-el-observatorio-de-genero-impulsan-proyectos-contra-la-violencia-laboral', '4', NULL, NULL, NULL, 'Representantes de los tres organismos adhirieron a un convenio para trabajar proyectos referidos a la problemática de la violencia en el ámbito del trabajo.', 'blog/imported-87.jpg');
INSERT INTO "routes" VALUES ('242', 'La Justicia en los barrios', 'la-justicia-en-los-barrios', 'published', 'App\Models\Blog', '88', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/la-justicia-en-los-barrios', '4', NULL, NULL, NULL, 'El Consejo de la Magistratura de la Ciudad Autónoma de Buenos Aires inició, junto a los voluntarios del Poder Judicial, las charlas que forman parte del Programa de Acceso Comunitario a la Justicia. El mismo fue presentado el 8 de junio con el fin de “llevar la Justicia al plano real”.', 'blog/imported-88.jpg');
INSERT INTO "routes" VALUES ('243', 'Inició el Programa de “Acceso Comunitario a la Justicia”', 'inicio-el-programa-de-acceso-comunitario-a-la-justicia', 'published', 'App\Models\Blog', '89', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/inicio-el-programa-de-acceso-comunitario-a-la-justicia', '4', NULL, NULL, NULL, 'El propósito de las charlas es transmitir a los vecinos información sobre los derechos de los niños, niñas y adolescentes, cuestiones de género, de personas con discapacidad y adultos mayores, y debatir situaciones en las que estos derechos pueden ser vulnerados. De esta forma, recalcó la Dra. Basterra, el Consejo de la Magistratura de la CABA pretende “sacar a la justicia –y a las personas que la representan– del escritorio, cruzar el expediente y acercarse a donde vive la gente para aportar a ', 'blog/imported-89.jpg');
