INSERT INTO "routes" VALUES ('245', 'Designaron a las nuevas autoridades del Consejo de la Magistratura de la Ciudad', 'designaron-a-las-nuevas-autoridades-del-consejo-de-la-magistratura-de-la-ciudad', 'published', 'App\Models\Blog', '91', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/designaron-a-las-nuevas-autoridades-del-consejo-de-la-magistratura-de-la-ciudad', '4', NULL, NULL, NULL, 'El lunes 27 de junio, durante el plenario de consejeros, se designaron a las nuevas autoridades del Consejo de la Magistratura de la Ciudad. La Dra. Marcela Basterra será la nueva Vicepresidenta del Consejo y aclaró: “es un honor asumir el cargo”. La Presidencia del Consejo de la Magistratura seguirá a cargo de Enzo Pagani.', 'blog/imported-91.jpg');
