INSERT INTO "routes" VALUES ('251', 'A 20 años de la Constitución CABA. Jornadas de reflexión en la Legislatura porteña', 'a-20-anos-de-la-constitucion-caba-jornadas-de-reflexion-en-la-legislatura-portena', 'published', 'App\Models\Blog', '97', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/a-20-anos-de-la-constitucion-caba-jornadas-de-reflexion-en-la-legislatura-portena', '4', NULL, NULL, NULL, 'El martes 4 de octubre se cumplen 20 años de la Constitución de la Ciudad Autónoma de Buenos Aires que se sancionó el martes 1 de octubre de 1996. Con motivo de reflexión, se llevarán a cabo las Jornadas en conmemoración del traspaso de autonomía. En diversos paneles deliberativos sobre diferentes temáticas, participarán historiadores, políticos, consultores, ex-constituyentes, legisladores, juristas y catedráticos. Durante una extensa jornada se debatirá sobre la importancia histórica, política', 'blog/imported-97.jpg');
