INSERT INTO "routes" VALUES ('255', 'Jornadas sobre Segundo Plan Estratégico de Tierra del Fuego', 'jornadas-sobre-segundo-plan-estrategico-de-tierra-del-fuego', 'published', 'App\Models\Blog', '101', '2026-07-21 18:27:59', '2026-07-21 18:56:27', 'default', 'novedades/jornadas-sobre-segundo-plan-estrategico-de-tierra-del-fuego', '4', NULL, NULL, NULL, 'La Dra. Marcela I. Basterra fue invitada como Vicepresidenta del Consejo de la Magistratura a las Jornadas que dan apertura al “Segundo Plan Estratégico del Poder Judicial de Tierra del Fuego Juzgado — Dependencias Judiciales”, el pasado jueves 10 de noviembre.', NULL);
INSERT INTO "routes" VALUES ('256', 'Jornada sobre Justicia y Comunicación', 'jornada-sobre-justicia-y-comunicacion', 'published', 'App\Models\Blog', '102', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/jornada-sobre-justicia-y-comunicacion', '4', NULL, NULL, NULL, 'El consejo de la Magistratura junto con la Facultad de Derecho y el Foro de Periodismo Argentino organizan estas jornadas enfocadas en el Diálogo con la Justicia el día jueves 24 de noviembre de 14 a 18h en el Salón Verde de Derecho (UBA).', 'blog/imported-102.jpg');
INSERT INTO "routes" VALUES ('257', 'Encontrando la puerta hacia la Justicia', 'encontrando-la-puerta-hacia-la-justicia', 'published', 'App\Models\Blog', '103', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/encontrando-la-puerta-hacia-la-justicia', '4', NULL, NULL, NULL, 'El martes 1 de diciembre se reunieron en el Barrio de INTA (ex Villa 19) más de 60 mujeres, junto a sus hijas y sus hijos, para compartir una merienda en el marco del evento que le dio cierre al Programa de Acceso Comunitario a la Justicia del Consejo de la Magistratura de la Ciudad de Buenos Aires.', 'blog/imported-103.jpg');
INSERT INTO "routes" VALUES ('258', 'Convenio con Universidad Tor Vergata de Roma', 'convenio-con-universidad-tor-vergata-de-roma', 'published', 'App\Models\Blog', '104', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/convenio-con-universidad-tor-vergata-de-roma', '4', NULL, NULL, NULL, 'La Dra. Basterra, Vicepresidenta del Consejo de la Magistratura, y el Dr. Federico Penna del Centro de Estudios Jurídicos Latinoamericanos de la Universidad Tor Vergata de Roma, firmaron un convenio de marco de cooperación académica.', 'blog/imported-104.jpg');
INSERT INTO "routes" VALUES ('259', 'Presentación de Derecho al Cuento. Acceso a la Justicia como prioridad también en el 2017', 'presentacion-de-derecho-al-cuento-acceso-a-la-justicia-como-prioridad-tambien-en-el-2017', 'published', 'App\Models\Blog', '105', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/presentacion-de-derecho-al-cuento-acceso-a-la-justicia-como-prioridad-tambien-en-el-2017', '4', NULL, NULL, NULL, 'El Proyecto Teatro de Papel: Una función justa realizará un encuentro para dar cierre a las actividades de 2016. Luego de que más de 4.000 niños y niñas hayan disfrutado de las Funciones de Teatro con Contenido de Derechos, 100 de ell@s asistirán a un encuentro donde se llevará a cabo la presentación de “Derecho al cuento”. Cinco cuentos creados por chicos y chicas de la Ciudad de Buenos Aires de distintas organizaciones, junto a los artistas que encabezaron la actividad y los voluntarios del Po', 'blog/imported-105.jpg');
