INSERT INTO "routes" VALUES ('261', 'Nuevo libro: “Constitución de la Ciudad Autónoma de Buenos Aires. Edición Comentada”', 'nuevo-libro-constitucion-de-la-ciudad-autonoma-de-buenos-aires-edicion-comentada', 'published', 'App\Models\Blog', '107', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/nuevo-libro-constitucion-de-la-ciudad-autonoma-de-buenos-aires-edicion-comentada', '4', NULL, NULL, NULL, 'El Consejo de la Magistratura de la Ciudad presenta el libro: “Constitución de la Ciudad Autónoma de la Ciudad Autónoma de Buenos Aires. Edición Comentada”, publicado por la Editorial Jusbaires, el lunes 19 de diciembre de 2016 a las 17h en el Salón Azul de la Facultad de Derecho de la UBA.', 'blog/imported-107.jpg');
