INSERT INTO "routes" VALUES ('265', 'Reconocimiento a los voluntarios que integran el programa de Acceso Comunitario a la Justicia', 'reconocimiento-a-los-voluntarios-que-integran-el-programa-de-acceso-comunitario-a-la-justicia', 'published', 'App\Models\Blog', '111', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/reconocimiento-a-los-voluntarios-que-integran-el-programa-de-acceso-comunitario-a-la-justicia', '4', NULL, NULL, NULL, 'Treinta voluntarios y voluntarias del Poder Judicial participaron del Programa de Acceso Comunitario a la Justicia durante el 2016, dando más de cien charlas sobre derechos en quince villas y barrios vulnerables de la Ciudad de Buenos Aires. Este es nuestro reconocimiento y agradecimiento a cada uno y a cada una de ell@s.', 'blog/imported-111.jpg');
INSERT INTO "routes" VALUES ('266', 'Inicia el ciclo 2017 de Una Función Justa en la Villa 31', 'inicia-el-ciclo-2017-de-una-funcion-justa-en-la-villa-31', 'published', 'App\Models\Blog', '112', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/inicia-el-ciclo-2017-de-una-funcion-justa-en-la-villa-31', '4', NULL, NULL, NULL, 'La línea Teatro de Papel –Una Función Justa– del Programa de Acceso Comunitario a la Justicia es una de las actividades que el Consejo de la Magistratura coordina en los barrios más vulnerables de la Ciudad de Buenos Aires para, en palabras de la Dra. Basterra, Vicepresidenta del Consejo, “acercar la justicia a los barrios”. El equipo que lleva adelante el proyecto está formado por 30 voluntarios y voluntarias del Poder Judicial y ya lleva alcanzados a más de 4 mil niños y niñas de la ciudad. En', 'blog/imported-112.jpg');
