INSERT INTO "routes" VALUES ('269', '#8M: Un día para seguir trabajando por la igualdad de Derechos', '8m-un-dia-para-seguir-trabajando-por-la-igualdad-de-derechos', 'published', 'App\Models\Blog', '115', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/8m-un-dia-para-seguir-trabajando-por-la-igualdad-de-derechos', '4', NULL, NULL, NULL, 'El miércoles 8 de marzo en el marco del Día Internacional de la Mujer, la Dra. Marcela Basterra, Vicepresidenta del Consejo de la Magistratura de CABA, participó de una Mesa Redonda de Mujeres invitada por la Dra. Adriana Donato, Presidenta del Consejo de la Magistratura de la Nación. En el encuentro se abordaron temas para seguir concientizando sobre la lucha de mujeres que hace años vienen trabajando por los derechos de género y de minorías.', 'blog/imported-115.jpg');
INSERT INTO "routes" VALUES ('270', 'Perspectiva de Género en el Consejo de la Magistratura', 'perspectiva-de-genero-en-el-consejo-de-la-magistratura', 'published', 'App\Models\Blog', '116', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/perspectiva-de-genero-en-el-consejo-de-la-magistratura', '4', NULL, NULL, NULL, 'El martes 14 de marzo la Dra. Marcela Basterra, Vicepresidenta del Consejo de la Magistratura CABA y la Consejera Vanesa Ferrazzuolo, participaron en un desayuno de trabajo organizado por la Lic. Silvina Pedreira de la Dirección de Relaciones con la Comunidad del Consejo. El encuentro propició un diálogo en el que se convocó a diferentes especialistas para hablar sobre la “incorporación de la perspectiva de género en los nuevos desafíos del Consejo de la Magistratura de la CABA”.', 'blog/imported-116.jpg');
INSERT INTO "routes" VALUES ('271', '#AccesoJusticia se amplía en 2017', 'accesojusticia-se-amplia-en-2017', 'published', 'App\Models\Blog', '117', '2026-07-21 18:27:59', '2026-07-21 18:56:10', 'default', 'novedades/accesojusticia-se-amplia-en-2017', '4', NULL, NULL, NULL, 'Este mes retomamos el Ciclo de Charlas sobre Derechos Humanos que forman parte del Programa de Acceso Comunitario a la Justicia del Consejo de la Magistratura de la Ciudad de Buenos Aires. La Vicepresidenta, Marcela I. Basterra, junto con la Unidad de Fortalecimiento Institucional y Planificación Estratégica dirigida por el Dr. Alejandro Fernández, impulsan este Programa que ya lleva brindadas 500 charlas y más de 170 obras de teatro “Una función justa” para niños/as de los barrios más vulnerabl', 'blog/imported-117.jpg');
