INSERT INTO "routes" VALUES ('297', 'La Dra. Basterra se reunió con alumnos de la Facultad de Derecho de la UCA', 'la-dra-basterra-se-reunio-con-alumnos-de-la-facultad-de-derecho-de-la-uca', 'published', 'App\Models\Blog', '143', '2026-07-21 18:28:00', '2026-07-21 18:56:11', 'default', 'novedades/la-dra-basterra-se-reunio-con-alumnos-de-la-facultad-de-derecho-de-la-uca', '4', NULL, NULL, NULL, 'Los alumnos de primer año de la Facultad de Derecho de la Universidad Católica de Buenos Aires recorrieron la sede del Consejo de la Magistratura y de la Editorial Jusbaires.', 'blog/imported-143.jpg');
