INSERT INTO "routes" VALUES ('301', 'Discapacidad y Derechos', 'discapacidad-y-derechos', 'published', 'App\Models\Blog', '147', '2026-07-21 18:28:00', '2026-07-21 18:56:11', 'default', 'novedades/discapacidad-y-derechos', '4', NULL, NULL, NULL, '“Empecemos a capacitar para que la sociedad se concientice en remover los obstáculos para el efectivo cumplimiento de los derechos”, afirmó la Dra. Marcela I. Basterra en su encuentro con Nicolás Stupenengo, empleado del Consejo de la Magistratura y voluntario del Programa de Acceso Comunitario a la Justicia.', 'blog/imported-147.jpg');
INSERT INTO "routes" VALUES ('302', 'El Programa de #AccesoJusticia festejó el Día del Niño en la Villa 31', 'el-programa-de-accesojusticia-festejo-el-dia-del-nino-en-la-villa-31', 'published', 'App\Models\Blog', '148', '2026-07-21 18:28:00', '2026-07-21 18:56:11', 'default', 'novedades/el-programa-de-accesojusticia-festejo-el-dia-del-nino-en-la-villa-31', '4', NULL, NULL, NULL, 'El miércoles 30 de agosto el equipo del Programa de Acceso Comunitario a la Justicia realizó una jornada de actividades dedicadas a los niños y niñas que viven en la villa 31. El evento se llevó a cabo con 15 voluntarios del Programa y contó con la participación de alrededor de 200 menores que se acercaron a celebrar el mes del niño junto a sus padres.', 'blog/imported-148.jpg');
